    // FOOTER
    "footer.wordmark": "Filippo Boi",

    // HOME
    "home.hero.headline": "Ragiono per immagini, progetto strutture visive.",
    "home.hero.tagline": "Filippo Boi — Media Designer",
    "home.hero.meta": "Bologna | Cagliari",
    "home.projects.title": "Progetti selezionati",
    "home.projects.cta": "Tutti i lavori",
    "home.approach.title": "Approccio",
    "home.approach.01.cat": "Sistemico",
    "home.approach.01.desc": "Ogni progetto è un sistema prima che un singolo output. Costruisco linguaggi visivi coerenti, non soluzioni isolate.",
    "home.approach.02.cat": "Relazionale",
    "home.approach.02.desc": "Il design nasce dal contatto con le persone. Ascolto, osservo e traduco in forma ciò che emerge dalla relazione.",
    "home.approach.03.cat": "Sperimentale",
    "home.approach.03.desc": "La ricerca precede e informa l'esecuzione. Il processo non è un mezzo — è parte del risultato.",
    "home.approach.04.cat": "Narrativo",
    "home.approach.04.desc": "Ogni progetto racconta qualcosa prima ancora di comunicare. Il senso viene prima della forma.",
    "home.profile.title": "Profilo",
    "home.profile.intro": "Progetto sistemi visivi per dare forma, coerenza e direzione alla comunicazione. Il mio lavoro nasce dall'ascolto e vive di contesti: ogni cliente, ogni territorio, ogni comunità chiede un linguaggio diverso, e il mio compito è trovarlo insieme a chi ho davanti. Attraverso graphic design, installazioni e pratiche artistiche con la stessa postura — quella di chi progetta con le persone, non solo per loro. Ogni progetto è un sistema visivo, prima che un singolo output.",
    "home.cta.contact": "Hai un progetto in mente? Parliamo.",

